\label{ass:dissipative}
{Assume that {\(a_1>0>a_2\)}.}
{For each \(i=1,2\), assume that \(0<q_i<\alpha_i\),
\(b_{i0}>0\), \(r_{i0}>1\), and}
\begin{equation}
	{
		{\left\{
		\begin{aligned}
			r_{i0}-1&>r_{i1}-2 &&\text{if }b_{i1}>0,\\
			r_{i0}-1&>r_{i2}-\alpha_i &&\text{if }b_{i2}>0.
		\end{aligned}
		\right.}
	}
	\label{eq:dissipative-dominance}
\end{equation}
If \(q_i>1\), assume in addition that
\begin{eqnarray*}
 q_i+r_{i1}-2\ge0\quad\text{if }b_{i1}>0,
 \qquad
 q_i+r_{i2}-\alpha_i\ge0\quad\text{if }b_{i2}>0.
\end{eqnarray*}

\label{ass:cooperative-dissipation}
	The interaction coefficients satisfy \(a_1,a_2>0\), and
	\begin{equation}
		\frac{\theta_1}{r_{10}}+\frac{\kappa_1}{r_{20}}\le1,
		\qquad
		\frac{\kappa_2}{r_{10}}+\frac{\theta_2}{r_{20}}\le1.
		\label{eq:cooperative-powers}
	\end{equation}
	If both equalities hold in \eqref{eq:cooperative-powers}, we further assume that
	\begin{equation}
		\left(\frac{a_1}{b_{10}}\right)^{\kappa_2/r_{10}}
		\left(\frac{a_2}{b_{20}}\right)^{\kappa_1/r_{20}}<1.
		\label{eq:cooperative-critical}
	\end{equation}

\label{thm:cooperative-noimm-boundary}
Assume \eqref{eq:cooperative-regularity} and
\Cref{ass:cooperative-dissipation} hold with
\(\iota_1=\iota_2=0\). 
Suppose that one of the following conditions holds:
\begin{enumerate}[label=\textup{(\roman*)}]
\item The interaction powers satisfy
\begin{equation}
 \frac{\theta_1}{r_{10}}+\frac{\kappa_1}{r_{20}}
 =\frac{\kappa_2}{r_{10}}+\frac{\theta_2}{r_{20}}=1.
 \label{eq:cooperative-critical-powers}
\end{equation}
\item \(b_{11}+b_{12}>0\), \(b_{21}+b_{22}>0\), and, for
at least one \(i\in\{1,2\}\),
\begin{equation}
 (r_{i1}<2\ \text{if}\ b_{i1}>0)
 \quad\text{or}\quad
 (r_{i2}<\alpha_i\ \text{if}\ b_{i2}>0).
 \label{eq:cooperative-accessible-noise}
\end{equation}
\item \(b_{11}+b_{12}>0\), \(b_{21}+b_{22}>0\), and
\begin{equation*}
 \max_{i=1,2}
 \min\bigl\{r_{i1}-2\ \text{if}\ b_{i1}>0,\;
             r_{i2}-\alpha_i\ \text{if}\ b_{i2}>0\bigr\}
 <(\theta_1+\kappa_1)\wedge(\theta_2+\kappa_2)-1.
\end{equation*}
\end{enumerate}
Then a probability \(\pi\) is invariant for the SSP \(Z^{\tau_0}\) if and only if \(\pi(\partial E)=1\). For the
CWP \(Z\), \(\delta_{(0,0)}\) is the unique
invariant probability.

\label{thm:cooperative-interior}
Assume \eqref{eq:cooperative-regularity} and
\Cref{ass:cooperative-dissipation} hold with
\(\iota_1=\iota_2=0\). For \(i=1,2\), set
\[
 r_i:=\min\bigl\{r_{i0}-1,\;
          r_{i1}-2\ \text{if }b_{i1}>0,\;
          r_{i2}-\alpha_i\ \text{if }b_{i2}>0\bigr\}.
\]
Suppose that \(r_i>\theta_i-1\) for \(i=1,2\) and that either
\begin{enumerate}[label=\textup{(\roman*)}]
\item  \((r_1-\theta_1+1)(r_2-\theta_2+1) >\kappa_1\kappa_2\); or
\item \( (r_1-\theta_1+1)(r_2-\theta_2+1) =\kappa_1\kappa_2\) and
\[
 \left(\frac{a_1}{{b_1}}\right)^{r_2-\theta_2+1}
 \left(\frac{a_2}{{b_2}}\right)^{\kappa_1}>1,
\]
where, for \(i=1,2\),
\begin{eqnarray*}
 {b_i}:= b_{i0}\1_{\{r_{i0}-1= r_i \}}
 +(r_i+1)b_{i1}\1_{\{r_{i1}-2= r_i\}}+\frac{\Gamma(r_i+\alpha_i)}
 {\Gamma(r_i+1)\Gamma(\alpha_i)}
 b_{i2}\1_{\{r_{i2}-\alpha_i=r_i\}}.
\end{eqnarray*}
\end{enumerate}
Then the CWP and the SSP have a common nondegenerate
invariant probability \(\pi_\circ\) satisfying, for some
\(\eta,\zeta>0\),
\[
 \int_{E^\circ}
 \bigl(x^{r_{10}}+y^{r_{20}}+x^{-\eta}+y^{-\zeta}\bigr)
 \,\pi_\circ(\,\mathrm d x,\,\mathrm d y)<\infty.
\]

\label{ass:weighted-dissipation}
	One of the
	following conditions holds:
	\begin{enumerate}[label=\textup{(\roman*)}]
		\item \(a_1,a_2\le0\).

		\item \(a_1>0\), \(a_2\le0\), and
		\begin{equation}
			\frac{\theta_1}{r_{10}}+\frac{\kappa_1}{r_{20}}
			-\1_{\{a_2<0\}}
			\left(
			\frac{\kappa_2}{r_{10}}+\frac{\theta_2}{r_{20}}-1
			\right)^+
		 \left(\frac{\theta_1}{\kappa_2}
             \wedge\frac{\kappa_1}{\theta_2}\right)
			\le1.
			\label{eq:mixed-parameter-condition}
		\end{equation}
		\item \Cref{ass:cooperative-dissipation} holds.
	\end{enumerate}

\label{thm:imm-existence}
Assume \eqref{eq:imm-regularity} and
\Cref{ass:weighted-dissipation} hold. Then the transition semigroup $(P_t)_{t \ge 0}$
of \eqref{eq:model} admits an invariant probability.
Moreover, there exist constants \(c, c_1>0\) and \(C_0\ge0\),
depending only on the parameters of \eqref{eq:model},
such that every invariant probability \(\pi\) satisfies
\begin{equation}
	\left\{
	\begin{aligned}
		&\int_E\bigl(b_{10}x^{r_{10}}+c_1b_{20}y^{r_{20}}
		-a_1x^{\theta_1}y^{\kappa_1}
		-c_1a_2x^{\kappa_2}y^{\theta_2}\bigr)
		\pi(\,\mathrm d x,\,\mathrm d y)
		\le\iota_1+c_1\iota_2,\\
		&\int_E\bigl(x^{r_{10}}+y^{r_{20}}\bigr)
		\pi(\,\mathrm d x,\,\mathrm d y)
		\le\frac{\iota_1+c_1\iota_2+C_0}{c}<\infty.
	\end{aligned}
	\right.
	\label{eq:imm-moment}
\end{equation}

\label{cor:stationary-balance}
 Under the assumptions of \Cref{thm:imm-existence}, suppose in addition that
 \begin{equation}
  r_{ij}\le r_{i0}\quad\text{if }b_{ij}>0,
  \qquad i,j=1,2.
  \label{eq:noise-moment-order}
 \end{equation}
 Then 
 \begin{enumerate}[label=\textup{(\roman*)}]
 \item The constants \(c,c_1,C_0\) in \Cref{thm:imm-existence} can be chosen
 so that every invariant probability \(\pi\) satisfies
 \begin{equation}
  \int_E\bigl(b_{10}x^{r_{10}}+c_1b_{20}y^{r_{20}}
  -a_1x^{\theta_1}y^{\kappa_1}-c_1a_2x^{\kappa_2}y^{\theta_2}\bigr)
  \,\pi(\,\mathrm d x,\,\mathrm d y)=\iota_1+c_1\iota_2.
  \label{eq:stationary-balance}
 \end{equation}
 \item If \(a_1>0>a_2\) and
 \begin{equation}
  \theta_1=\kappa_2,\qquad \theta_2=\kappa_1,
  \label{eq:balanced-interactions}
 \end{equation}
 then \Cref{ass:weighted-dissipation}\textup{(ii)} holds automatically,
one may take \(c_1=a_1/(-a_2)\), and every invariant probability \(\pi\) satisfies
 \[
  b_{10}\int_E x^{r_{10}}\pi(\,\mathrm d x,\,\mathrm d y)
  +\frac{a_1}{-a_2}b_{20}\int_E y^{r_{20}}\pi(\,\mathrm d x,\,\mathrm d y)
  =\iota_1+\frac{a_1}{-a_2}\iota_2.
 \]
 \end{enumerate}

\label{cor:individual-interaction-balances}
Assume \eqref{eq:imm-regularity}, \eqref{eq:noise-moment-order} and
\Cref{ass:weighted-dissipation} hold. If \(a_1a_2>0\), then with all integrals finite, every
invariant probability \(\pi\) satisfies the following:
\begin{equation}
 \left\{
 \begin{aligned}
 b_{10}\int_E x^{r_{10}}\pi(\,\mathrm d x, \,\mathrm d y)
 &=\iota_1+a_1\int_E x^{\theta_1}y^{\kappa_1}\pi(\,\mathrm d x, \,\mathrm d y),\\
 b_{20}\int_E y^{r_{20}}\pi(\,\mathrm d x, \,\mathrm d y)
 &=\iota_2+a_2\int_E x^{\kappa_2}y^{\theta_2}\pi(\,\mathrm d x, \,\mathrm d y).
 \end{aligned}
 \right.
 \label{eq:individual-interaction-balances}
\end{equation}

\label{cor:sqrt-main}
Assume \eqref{eq:imm-regularity} and
\Cref{ass:weighted-dissipation} hold for \eqref{eq:sqrt-system} with \(\iota_1,\iota_2>0\). Then
\begin{enumerate}[label=\textup{(\roman*)}]
\item The process $Z$ admits an invariant probability.
Every invariant probability \(\pi\) is concentrated on \(E^\circ\),
has support \(E\), and satisfies \eqref{eq:imm-moment}
and \eqref{eq:stationary-balance}.
\item If
\begin{equation}
 \iota_1\ge b_{11},\qquad \iota_2\ge b_{21},
 \label{eq:Feller-thresholds}
\end{equation}
then the invariant probability \(\pi\) is unique and
\(\Pi_T^{(x_0,y_0)}\Rightarrow\pi\) as \(T\to\infty\)
for every \((x_0,y_0)\in E\).
\end{enumerate}

\label{lem:parameter-drift}
Assume that \eqref{eq:imm-regularity} and
\Cref{ass:weighted-dissipation} hold. Then there exist constants
\(c, c_1>0\) and \(C_0\ge0\) such that the functions \(V_0, W_0\) defined by \eqref{SVW}
satisfy
\begin{equation}
 \mathcal L V_0(x,y)\le \iota_1+c_1\iota_2+C_0
 -cW_0(x,y),
 \qquad (x,y)\in E.
 \label{eq:weighted-dissipation}
\end{equation}

\label{lem:imm-lyapunov}
	Assume that \eqref{eq:imm-regularity} and
	\Cref{ass:weighted-dissipation} hold.
	Let \(c_1,c>0\) and \(C_0\ge0\) satisfy
	\eqref{eq:weighted-dissipation}.
	Then the nonnegative solution \(Z\) of \eqref{eq:model}
	is nonexplosive, and there exists a constant \(C>0\) such that,
	for every \((x_0,y_0)\in E\),
	\begin{equation}
		\mathbb E_{x_0,y_0}V_0(Z_t)
		\le e^{-t}V_0(x_0,y_0)+C(1-e^{-t}),
		\qquad t\ge0,
		\label{eq:V-first-moment}
	\end{equation}
	and
	\begin{equation}
		\mathbb E_{x_0,y_0}\int_0^T
		\bigl(\iota_1+c_1\iota_2+C_0-\mathcal L V_0(Z_s)\bigr)\,\mathrm d s
		\le  V_0(x_0,y_0)+(\iota_1+c_1\iota_2+C_0)T,
		\qquad T>0,
		\label{eq:imm-occupation-bound}
	\end{equation}
		where \(V_0\) is the function defined in \eqref{SVW}. Moreover, for every compact \(K\subset E\) and \(t>0\),
	\[
	\lim_{R\to\infty}\sup_{(x_0,y_0)\in K}
	\mathbb P_{x_0,y_0}(\tau_R^+\le t)=0.
	\]

\label{lem:predator-source-occupation}
Under \Cref{ass:dissipative}, the SSP $Z^{\tau_0}$ is
conservative, and there exist constants \(C,c>0\) such that
\begin{equation}
 \mathcal L H(x,y)\le C-cW(x,y),
 \qquad (x,y)\in E^\circ,
 \label{eq:Foster-H}
\end{equation}
and
\begin{equation}
 {\frac1T\mathbb E_{x_0,y_0}\int_0^{T\wedge\tau_0}W(Z_s)\,\mathrm d s
 \le \frac Cc+\frac{H(x_0,y_0)}{cT},
 \qquad (x_0,y_0)\in E^\circ,\quad T>0.}
 \label{eq:source-occupation}
\end{equation}

\label{lem:cw-occupation}
Suppose that \Cref{ass:dissipative} and
\eqref{eq:boundary-compatible} hold.
{Then the CWP $Z$ is conservative. Moreover, there exist constants \(C,c>0\) such that, for every
\((x_0,y_0)\in E\) and \(t\ge0\),}
\begin{equation}
 {\mathbb E_{x_0,y_0}H(Z_t)
 +c\mathbb E_{x_0,y_0}\int_0^t W(Z_s)\,\mathrm d s
 \le H(x_0,y_0)+Ct.}
 \label{eq:cw-global-Foster}
\end{equation}
Consequently, \(\{\Pi_T^{(x_0,y_0)}:T\ge1\}\) is tight
for every \((x_0,y_0)\in E\).

{
With the change of variables \(z=uv\), the identities follow
from the power-integral formulas in \cite[Lemma~11]{XiongYangZhouCompeting}.
}

For \(p,q>0\), consider \(\chi(x)x^{-p}\) and \(\chi(y)y^{-q}\), where $\chi(\cdot)$ is defined in the beginning of \Cref{sec:cooperative-noimm-proofs}.
Both functions are nonnegative and nonincreasing in each coordinate.
For \(0<x\le1\), \(\chi(x)x^{-p}=x^{-p}\) and
\(\chi(x+z)(x+z)^{-p}\le(x+z)^{-p}\).
On \(1\le x\le2\), the derivatives and L\'evy integral of
\(\chi(x)x^{-p}\) are bounded; for \(x\ge2\), they vanish.
The second coordinate is treated in the same way.
Thus by \Cref{lem:cooperative-power-calculus},
\begin{equation}
\begin{aligned}
 \mathcal L\bigl(\chi(x)x^{-p}\bigr)\le{}&C+\1_{\{x\le1\}}p x^{-p}
 \biggl(b_{10}x^{r_{10}-1}+(p+1)b_{11}x^{r_{11}-2}\\
 &\hspace{3em}+\frac{\Gamma(p+\alpha_1)}
 {\Gamma(p+1)\Gamma(\alpha_1)}b_{12}x^{r_{12}-\alpha_1}
 -a_1x^{\theta_1-1}y^{\kappa_1}\biggr),\\
 \mathcal L\bigl(\chi(y)y^{-q}\bigr)\le{}&C+\1_{\{y\le1\}}q y^{-q}
 \biggl(b_{20}y^{r_{20}-1}+(q+1)b_{21}y^{r_{21}-2}\\
 &\hspace{3em}+\frac{\Gamma(q+\alpha_2)}
 {\Gamma(q+1)\Gamma(\alpha_2)}b_{22}y^{r_{22}-\alpha_2}
 -a_2y^{\theta_2-1}x^{\kappa_2}\biggr)
\end{aligned}
\label{eq:cooperative-cutoff-generator}
\end{equation}
for some constant \(C>0\), uniform in \((x,y)\in E^\circ\).
The interaction terms omitted on the cutoff intervals are
nonpositive.

Suppose first that \textup{(i)} holds. Choose
\[
 \frac{\kappa_2}{r_2-\theta_2+1}<\rho<\frac{r_1-\theta_1+1}{\kappa_1},
 \qquad p=q\rho,
\]
where \(q>0\) will be taken sufficiently large. Put
\[
 A=p+1-\theta_1,\qquad B=q+1-\theta_2,
 \qquad
 \eta=\frac{AB-\kappa_1\kappa_2}{B+\kappa_1},\qquad
 \zeta=\frac{AB-\kappa_1\kappa_2}{A+\kappa_2}.
\]
For large \(q\), the above four quantities are positive. Moreover,
as \(q\to\infty\),
\begin{align*}
 p-\eta
 &=\theta_1-1+\kappa_1\frac{A+\kappa_2}{B+\kappa_1}
 \rightarrow\theta_1-1+\kappa_1\rho<r_1,\\
 q-\zeta
 &=\theta_2-1+\kappa_2\frac{B+\kappa_1}{A+\kappa_2}
 \rightarrow\theta_2-1+\frac{\kappa_2}{\rho}<r_2.
\end{align*}
Choose \(q\) large enough such that \(p-\eta<r_1\) and
\(q-\zeta<r_2\). By Young's inequality,
\[ {
	\frac{B}{B+\kappa_1}x^{-A}y^{\kappa_1}
	+\frac{\kappa_1}{B+\kappa_1}x^{\kappa_2}y^{-B}
	 \ge
	\bigl(x^{-A}y^{\kappa_1}\bigr)^{B/(B+\kappa_1)}
	\bigl(x^{\kappa_2}y^{-B}\bigr)^{\kappa_1/(B+\kappa_1)} 
	=x^{-\eta} }
 \]
and 
\begin{eqnarray*}
 \frac{\kappa_2}{A+\kappa_2}x^{-A}y^{\kappa_1}
 +\frac{A}{A+\kappa_2}x^{\kappa_2}y^{-B}
  \ge y^{-\zeta}.
\end{eqnarray*}
Consequently,
\[
 x^{-A}y^{\kappa_1}+x^{\kappa_2}y^{-B}
 \ge x^{-\eta}\vee y^{-\zeta}
 \ge\frac12(x^{-\eta}+y^{-\zeta}).
\]
Since \(A>\eta\) and \(B>\zeta\), separating the regions
\(x,y\le1\), \(x\le1<y\), \(y\le1<x\), and \(x,y>1\), we have
\begin{equation}
 \1_{\{x\le1\}}x^{-A}y^{\kappa_1}
 +\1_{\{y\le1\}}x^{\kappa_2}y^{-B}
 \ge\frac12(x^{-\eta}+y^{-\zeta})-1.
 \label{eq:cooperative-cutoff-coercivity}
\end{equation}
For \(\beta_1\ge r_1-p>-\eta\),
\(\beta_2\ge r_2-q>-\zeta\), and every \(\varepsilon>0\),
there is a constant \(C_\varepsilon>0\) such that
\begin{equation}
 \1_{\{x\le1\}}x^{\beta_1}
 \le\varepsilon x^{-\eta}+C_\varepsilon,
 \qquad
 \1_{\{y\le1\}}y^{\beta_2}
 \le\varepsilon y^{-\zeta}+C_\varepsilon.
 \label{eq:cooperative-power-absorption}
\end{equation}
 Combining
\eqref{eq:cooperative-cutoff-generator},
\eqref{eq:cooperative-cutoff-coercivity}, and
\eqref{eq:cooperative-power-absorption}, and choosing \(\varepsilon\) sufficiently small shows that
\begin{equation}
\mathcal L\bigl(\chi(x)x^{-p}\bigr)+\mathcal L\bigl(\chi(y)y^{-q}\bigr)
 \le C-\frac14((pa_1)\wedge (qa_2))(x^{-\eta}+y^{-\zeta})
 \qquad\text{on }E^\circ.
 \label{eq:cooperative-subcritical-drift}
\end{equation}
In this case, set \(\Psi(x,y)=\chi(x)x^{-p}+\chi(y)y^{-q}\).

Suppose now that \textup{(ii)} holds. For \(v>0\), let
\[
\begin{aligned}
 C_i(v):={}&b_{i0}\1_{\{r_{i0}-1=r_i\}}
 +(v+1)b_{i1}\1_{\{r_{i1}-2=r_i\}} +\frac{\Gamma(v+\alpha_i)}
 {\Gamma(v+1)\Gamma(\alpha_i)}
 b_{i2}\1_{\{r_{i2}-\alpha_i=r_i\}},
 \qquad i=1,2.
\end{aligned}
\]
Then \(C_i(r_i)=b_i\). Set \(\sigma=\kappa_2/(r_1-\theta_1+1)\).
There is a
constant \(R_0>0\) such that
\[
 \frac{b_1}{a_1}<R_0<
 \left(\frac{a_2}{b_2}\right)^{1/\sigma}.
\]
Choose \(\lambda_1,\lambda_2>0\) so that
\[
 \lambda_1r_1a_1
 =\sigma\lambda_2r_2a_2R_0^{-\sigma-1}.
\]
The function
\(R\mapsto\lambda_1r_1a_1R+
\lambda_2r_2a_2R^{-\sigma}\) attains its minimum at \(R_0\).
Consequently, for some \(c_0>0\),
\[
 \lambda_1r_1({b_1}-a_1R)
 +\lambda_2r_2({b_2}-a_2R^{-\sigma})\le-c_0,
 \qquad R>0.
\]
For \(\varepsilon\ge0\), let
\begin{eqnarray}\label{eqpq} 
 p=r_1+\frac{r_1-\theta_1+1}{\kappa_1}\varepsilon,
 \qquad q=r_2+\varepsilon,
\end{eqnarray}
and consider
\begin{eqnarray*}
 \frac{\lambda_1p[C_1(p)-a_1R]
 +\lambda_2qR^{-\varepsilon/\kappa_1}
       [C_2(q)-a_2R^{-\sigma}]}
 {1+R^{-\varepsilon/\kappa_1}}.
 \end{eqnarray*}
This quotient tends to \(-\infty\) at both endpoints of
\((0,\infty)\), uniformly for \(0\le\varepsilon\le1\),
and is at most \(-c_0/2\) when \(\varepsilon=0\).
Uniform continuity on compact intervals therefore gives
a sufficiently small \(\varepsilon\in(0,1)\) and
\(c_2>0\) such that
\begin{equation}
\begin{aligned}
\lambda_1p[C_1(p)-a_1R]
 +\lambda_2qR^{-\varepsilon/\kappa_1}
       [C_2(q)-a_2R^{-\sigma}] \le-c_2(1+R^{-\varepsilon/\kappa_1}),
 \qquad R>0.
\end{aligned}
\label{eq:cooperative-critical-scalar}
\end{equation}
Set
\[
 \eta=\frac{r_1-\theta_1+1}{\kappa_1}\varepsilon,
 \qquad
 \Psi(x,y)=\lambda_1\chi(x)x^{-p}+\lambda_2\chi(y)y^{-q}.
\]
With \(R=y^{\kappa_1}/x^{r_1-\theta_1+1}\), by the assumption
\((r_1-\theta_1+1)(r_2-\theta_2+1)=\kappa_1\kappa_2\), we have
\[
 y^{-\varepsilon}=x^{-\eta}R^{-\varepsilon/\kappa_1},
 \qquad
 \frac{x^{\kappa_2}}{y^{r_2-\theta_2+1}}=R^{-\sigma}.
\]
For \(0<x,y\le1\), \eqref{eq:cooperative-cutoff-generator}
and \eqref{eqpq} yield
\begin{align*}
 \mathcal L\Psi(x,y)\le{}&C+
 \lambda_1p x^{-\eta}[C_1(p)-a_1R+o(1)]+\lambda_2q y^{-\varepsilon}[C_2(q)-a_2R^{-\sigma}+o(1)]\\
 \le{}&C-c_2(x^{-\eta}+y^{-\varepsilon})
       +o(1)x^{-\eta}+o(1)y^{-\varepsilon},
\end{align*}
where the second inequality uses
\eqref{eq:cooperative-critical-scalar}.
Hence, for some \(r\in(0,1)\),
\[
 \mathcal L\Psi(x,y)\le C-\frac{c_2}{2}
 (x^{-\eta}+y^{-\varepsilon}),\qquad 0<x,y\le r.
\]
If \(x\le r<y\), \eqref{eq:cooperative-cutoff-generator}
instead gives, for suitable constants \(C,c_3,c_4>0\),
\[
 \mathcal L\Psi(x,y)
 \le-c_3x^{-\eta-r_1+\theta_1-1}+Cx^{-\eta}+C
 \le C-c_4x^{-\eta}.
\]
Interchanging the
coordinates treats \(y\le r<x\). On \(x,y\ge r\), the
positive terms and the two negative powers on the right hands of \eqref{eq:cooperative-cutoff-generator} are bounded.
Thus, after adjusting the constants,
\begin{equation}
 \mathcal L\Psi(x,y)\le C-c_5(x^{-\eta}+y^{-\varepsilon})
 \qquad\text{on }E^\circ.
 \label{eq:cooperative-critical-drift}
\end{equation}

In either case, choose \(c_1,c,C_0\) as in
\Cref{lem:parameter-drift}, and define $
 V(x,y):=S(x,y)+\Psi(x,y).$
By \eqref{eq:weighted-dissipation},
\eqref{eq:cooperative-subcritical-drift}, and
\eqref{eq:cooperative-critical-drift}, there are constants
\(\widetilde C,\widetilde c>0\) such that
\[
 \mathcal L V(x,y)\le
 \begin{cases}
 \widetilde C-\widetilde c\bigl(W_0(x,y)+x^{-\eta}+y^{-\zeta}\bigr),
       &\text{in case \textup{(i)}},\\
 \widetilde C-\widetilde c\bigl(W_0(x,y)+x^{-\eta}+y^{-\varepsilon}\bigr),
       &\text{in case \textup{(ii)}}.
 \end{cases}
\]
The result follows by \Cref{lem:interior-lyapunov}.

\label{lem:sharp-stationary-tests}
	Assume the hypotheses of \Cref{thm:cooperative-sharp}
	with \(\beta=1\). Let \(\pi\) be an invariant probability
	{ for either the CWP \(Z\) or the SSP \(Z^{\tau_0}\),}
	with \(\pi(E^\circ)=1\). Then {$\int_{E^\circ}(x/y+y/x)
	 \pi(\,\mathrm d x, \,\mathrm d y)<\infty.$} 
	Moreover, for every \(p,q>0\) with \(p+q=1\), the function
	\(f(x,y)=x^{-p}y^{-q}\) satisfies $
	\mathcal L f\in L^1(\pi)$ and $\int_{E^\circ}\mathcal L f\,\,\mathrm d\pi=0.$

\label{lem:localized-cir-comparison}
Let \(Z\) be a nonnegative solution to
\eqref{eq:sqrt-system} with initial state \((x_0,y_0)\in E\).
{Assume that {\(a_1>0>a_2\)},
\eqref{eq:balanced-interactions} holds, and
\(\kappa_1,\kappa_2>0\).}  For \(N>1+({x_0\vee y_0})\), set $\tau_N^+:=\inf\{t\ge0:X_t\vee Y_t\ge N\}$ and $c_{1,N}:=b_{10}N^{r_{10}-1}.$
Then there exists \(c_{2,N}>0\) such that the solutions {\(U^{(i,N)}=(U_t^{(i,N)})_{t\ge0}\), \(i=1,2\)} of
\[
\left\{
\begin{aligned}
 U_t^{(1,N)}
 &=x_0+\int_0^t\bigl(\iota_1-c_{1,N}U_s^{(1,N)}\bigr)\,\mathrm d s
 +\int_0^t\sqrt{2b_{11}U_s^{(1,N)}}\,\mathrm d B_1(s),\\
 U_t^{(2,N)}
 &=y_0+\int_0^t\left(\frac{\iota_2}{2}-c_{2,N}U_s^{(2,N)}\right)\,\mathrm d s
 +\int_0^t\sqrt{2b_{21}U_s^{(2,N)}}\,\mathrm d B_2(s),
\end{aligned}
\right.
\]
obey
\begin{equation}
 X_t\ge U_t^{(1,N)},
 \qquad Y_t\ge U_t^{(2,N)},
 \qquad 0\le t<\tau_N^+,
 \quad\text{almost surely}.
 \label{eq:cir-localized-comparison}
\end{equation}
If, in addition, \(\kappa_1\ge1\), set
{\(\widetilde c_{2,N}:=(-a_2)N^{\kappa_1+\kappa_2-1}
 +b_{20}N^{r_{20}-1}\)}, and let
\(\widetilde U^{(2,N)}:=(\widetilde U_t^{(2,N)})_{t\ge0}\) solve
\[
 \widetilde U_t^{(2,N)}=y_0
 +\int_0^t\bigl(\iota_2-\widetilde c_{2,N}\widetilde U_s^{(2,N)}\bigr)\,\mathrm d s
 +\int_0^t\sqrt{2b_{21}\widetilde U_s^{(2,N)}}\,\mathrm d B_2(s),
\]
then
\begin{equation}
 Y_t\ge\widetilde U_t^{(2,N)},
 \qquad 0\le t<\tau_N^+,
 \quad\text{almost surely}.
 \label{eq:cir-strengthened-comparison}
\end{equation}

\label{lem:generalized-cir-comparison}
Let \(Z\) be a nonnegative solution to
\eqref{eq:sqrt-system} with initial state \((x_0,y_0)\in E\).
Assume that \(\theta_i\ge1\), \(i=1,2\), and allow
{\(a_1,a_2\in\mathbb R\)}. For \(N>1+(x_0\vee y_0)\), set
\[
 d_{1,N}:=b_{10}N^{r_{10}-1}+(-a_1)^+N^{\theta_1+\kappa_1-1},
 \qquad
 d_{2,N}:=b_{20}N^{r_{20}-1}+(-a_2)^+N^{\theta_2+\kappa_2-1}.
\]
Let \(V^{(1,N)}\) and \(V^{(2,N)}\) solve
\[
\left\{
\begin{aligned}
 V_t^{(1,N)}
 &=x_0+\int_0^t\bigl(\iota_1-d_{1,N}V_s^{(1,N)}\bigr)\,\mathrm d s
 +\int_0^t\sqrt{2b_{11}V_s^{(1,N)}}\,\mathrm d B_1(s),\\
 V_t^{(2,N)}
 &=y_0+\int_0^t\bigl(\iota_2-d_{2,N}V_s^{(2,N)}\bigr)\,\mathrm d s
 +\int_0^t\sqrt{2b_{21}V_s^{(2,N)}}\,\mathrm d B_2(s).
\end{aligned}
\right.
\]
Then
\begin{equation}
 X_t\ge V_t^{(1,N)},\qquad Y_t\ge V_t^{(2,N)},
 \qquad 0\le t<\tau_N^+,\quad\text{almost surely}.
 \label{eq:cir-generalized-comparison}
\end{equation}

\label{prop:sqrt-boundary}
{Let \(Z=(X,Y)\) be a nonnegative, nonexplosive solution
of \eqref{eq:sqrt-system} starting from \((x_0,y_0)\in E\).}
\begin{enumerate}[label=\textup{(\roman*)}]
\item {If either {\(a_1>0>a_2\)},
\eqref{eq:balanced-interactions} holds, and
\(\kappa_1,\kappa_2>0\), or \(\theta_i\ge1\) for \(i=1,2\), then}
\begin{equation}
 \mathbb P(X_t>0,Y_t>0)=1,\qquad t>0.
 \label{eq:fixed-time-interior}
\end{equation}
\item {Assume that either {\(a_1>0>a_2\)},
\eqref{eq:balanced-interactions} holds, and \(\kappa_1\ge1\),
or \(\theta_i\ge1\) for \(i=1,2\).
If \eqref{eq:Feller-thresholds} holds, then}
\begin{equation}
 {\mathbb P(X_t>0,Y_t>0\text{ for every }t>0)=1.}
 \label{eq:pathwise-interior}
\end{equation}
\end{enumerate}

\label{lem:sqrt-interior-strong-feller}
	 {Assume \eqref{eq:imm-regularity} and \eqref{eq:Feller-thresholds}.}
	Then \(E^\circ\) is invariant, and the restriction of
	\((P_t)_{t\ge0}\) to \(E^\circ\) is strong Feller.

\label{lem:sqrt-interior-irreducibility}
For every \(t>0\), \((x_0,y_0)\in E^\circ\), and nonempty open
set \(O\subset E^\circ\), we have \(P_t((x_0,y_0),O)>0\).
